<?php declare(strict_types=1);require __DIR__.'/_bootstrap.php';require_admin();
function admin_order_colors(?string $value): array { $colors=json_decode((string)$value,true); return is_array($colors)?array_values(array_filter(array_map('strval',$colors))):($value?[$value]:[]); }
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id)redirect_to('orders.php');if(is_post()){verify_csrf($_POST['csrf']??'');$status=(string)($_POST['status']??'');if(in_array($status,['new','contacted','completed','cancelled'],true)){$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Order status updated.');}redirect_to('order.php?id='.$id);}$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$o=$s->fetch();if(!$o)redirect_to('orders.php');$colors=admin_order_colors($o['colors']??null);$itemsStmt=$pdo->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$itemsStmt->execute([$id]);$items=$itemsStmt->fetchAll();$pageTitle='Order '.$o['order_ref'];$active='orders';require __DIR__.'/includes/layout.php';?><div class="panel"><div class="panel-head"><h2>Order details</h2><span class="badge <?=e($o['status'])?>"><?=e($o['status'])?></span></div><div class="detail-grid"><div class="detail-box"><small>Customer</small><b><?=e($o['fullname'])?></b></div><div class="detail-box"><small>Phone</small><b><?=e($o['phone'])?></b></div><div class="detail-box"><small>Email</small><b><?=e($o['email']??'—')?></b></div><div class="detail-box"><small>Location</small><b><?=e($o['location'])?></b></div><div class="detail-box"><small>Fabric</small><b><?=e($o['fabric_type'])?></b></div><div class="detail-box"><small>Colours</small><b><?=e(implode(', ',$colors))?></b></div><div class="detail-box"><small>Measurement</small><b><?=e($o['measurement']==='yard'?'Per yard (36 inches)':'Per trouser length (45 inches)')?></b></div><div class="detail-box"><small>Quantity</small><b><?=e($o['quantity'])?></b></div><div class="detail-box"><small>Price / unit</small><b><?=money($o['unit_price'])?></b></div><div class="detail-box"><small>Subtotal</small><b><?=money($o['subtotal'])?></b></div><div class="detail-box"><small>Anniversary saving</small><b><?=money($o['discount'])?></b></div><div class="detail-box"><small>Total</small><b><?=money($o['total_amount'])?></b></div><div class="detail-box"><small>Date</small><b><?=e($o['created_at'])?></b></div><div class="detail-box"><small>Payment</small><b><?=e($o['payment_status']??'unpaid')?></b></div><div class="detail-box"><small>Paystack reference</small><b><?=e($o['paystack_reference']??'—')?></b></div><div class="detail-box"><small>Transaction ID</small><b><?=e((string)($o['paystack_transaction_id']??'—'))?></b></div><div class="detail-box"><small>Paid on</small><b><?=e($o['paid_at']??'—')?></b></div></div><div class="panel" style="margin-top:18px"><div class="panel-head"><h2>Cart items</h2><span class="badge"><?=e((string)count($items))?> item<?=count($items)===1?'':'s'?></span></div><div style="overflow:auto"><table class="data-table"><thead><tr><th>Fabric</th><th>Colour</th><th>Measurement</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody><?php foreach($items as $it): $itemColors=admin_order_colors($it['colors']??null); ?><tr><td><?=e($it['product_name'])?></td><td><?=e(implode(', ',$itemColors))?></td><td><?=e($it['measurement']==='yard'?'Per yard (36 inches)':'Per trouser length (45 inches)')?></td><td><?=e((string)$it['quantity'])?></td><td><?=money((float)$it['unit_price'])?></td><td><b><?=money((float)$it['line_total'])?></b></td></tr><?php endforeach; ?></tbody></table></div></div><div class="detail-box" style="margin-top:15px"><small>Customer note</small><b><?=nl2br(e($o['description']?:'No additional description.'))?></b></div><form method="post" style="margin-top:18px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="filterbar"><select name="status"><option value="new" <?=$o['status']==='new'?'selected':''?>>New</option><option value="contacted" <?=$o['status']==='contacted'?'selected':''?>>Contacted</option><option value="completed" <?=$o['status']==='completed'?'selected':''?>>Completed</option><option value="cancelled" <?=$o['status']==='cancelled'?'selected':''?>>Cancelled</option></select><button class="btn btn-gold">Update status</button><a class="btn btn-light" href="tel:<?=e($o['phone'])?>">Call</a><a class="btn btn-light" target="_blank" href="https://wa.me/<?=preg_replace('/\D+/','',$o['phone'])?>">WhatsApp</a><a class="btn btn-light" href="orders.php">Back</a></div></form></div><?php require __DIR__.'/includes/footer.php';?>
